#!/data/data/com.termux/files/usr/bin/bash
set -Eeuo pipefail
cd "$HOME/companyos"

STAMP="$(date +%Y%m%d_%H%M%S)"
BK=".companyos_backups/service_supervisor_stop_path_v28_$STAMP"
mkdir -p "$BK"
cp -a companyos/runtime/service_supervisor.py "$BK/"
cp -a companyos/runtime/runtime_control.py "$BK/"

echo "" | base64 -d > "$PREFIX/tmp/companyos_v28_patch.py"
python "$PREFIX/tmp/companyos_v28_patch.py"
rm -f "$PREFIX/tmp/companyos_v28_patch.py"

echo "" | base64 -d > scripts/companyos_verify_supervisor_stop_path_v28
chmod +x scripts/companyos_verify_supervisor_stop_path_v28

scripts/companyos_verify_supervisor_stop_path_v28 | tee .companyos_runtime/service_supervisor_stop_path_v28.log

git add companyos/runtime/service_supervisor.py scripts/companyos_verify_supervisor_stop_path_v28
git diff --cached --quiet || git commit -m "Repair ServiceSupervisor dedicated stop path"
BRANCH="$(git branch --show-current)"
[ -n "$BRANCH" ] && git push origin "$BRANCH" || true

echo "BACKUP=$BK"
echo "COMPANYOS_SERVICE_SUPERVISOR_STOP_PATH_V28=PASS"
